import { readdir, readFile, writeFile } from 'node:fs/promises';

// Keep the approved SVG sources editable; native Metro consumes this static registry.
const directory = new URL('../assets/illustrations/', import.meta.url);
const files = (await readdir(directory)).filter(file => file.endsWith('.svg')).sort();
const entries = await Promise.all(files.map(async file => [file.slice(0, -4), (await readFile(new URL(file, directory), 'utf8')).trim()]));
await writeFile(new URL('../src/ui/illustration-sources.ts', import.meta.url),
  '// Generated by node scripts/generate-illustrations.mjs. Edit assets/illustrations/*.svg.\n'
  + `export const illustrations = ${JSON.stringify(Object.fromEntries(entries), null, 2)} as const;\n`);
